INSERT INTO `scoring_configs` VALUES (1,'标准打分配置','[{\"key\": \"attention\", \"name\": \"吸引力\", \"scores\": {\"1-2\": \"开场无趣，完全无法吸引用户\", \"3-4\": \"开场平淡，缺乏吸引力，用户容易划走\", \"5-6\": \"开场普通，缺乏亮点，用户可能继续观看但容易流失\", \"7-8\": \"开场较吸引人，有一定好奇心，用户愿意继续观看\", \"9-10\": \"开场即抓住注意力，有强烈好奇心驱动，用户停留意愿极高\"}, \"description\": \"开场即抓住注意力，有强烈好奇心驱动\"}, {\"key\": \"logic\", \"name\": \"逻辑性\", \"scores\": {\"1-2\": \"完全没有逻辑，东一句西一句\", \"3-4\": \"逻辑混乱，卖点堆砌，缺乏条理\", \"5-6\": \"逻辑基本通顺，但部分衔接生硬\", \"7-8\": \"逻辑较清晰，卖点有条理，过渡自然\", \"9-10\": \"产品介绍层次分明，卖点递进清晰，从痛点→方案→证据→行动完美衔接\"}, \"description\": \"产品介绍层次分明，卖点递进清晰\"}, {\"key\": \"emotion\", \"name\": \"感染力\", \"scores\": {\"1-2\": \"完全无感情，机械式朗读\", \"3-4\": \"语气平淡，像念稿，缺乏情感\", \"5-6\": \"情感表达一般，缺乏感染力\", \"7-8\": \"有一定情感表达，能打动部分用户\", \"9-10\": \"情感充沛，能引发强烈共鸣，让用户产生\\\"我也想要\\\"的冲动\"}, \"description\": \"情感充沛，能引发强烈共鸣\"}, {\"key\": \"professional\", \"name\": \"专业性\", \"scores\": {\"1-2\": \"产品介绍错误百出，完全不专业\", \"3-4\": \"产品介绍有明显错误或夸大\", \"5-6\": \"产品介绍基本准确，但缺乏深度\", \"7-8\": \"产品介绍较专业，有一定数据支撑\", \"9-10\": \"产品知识准确，数据详实，有权威背书，用户信任度极高\"}, \"description\": \"产品知识准确，数据详实，有权威背书\"}]','你是一位专业的直播话术评审专家。请对用户提供的直播话术进行严格评分。\n\n## 评分维度（每项1-10分）\n\n### 1. 吸引力（Attention）\n- **9-10分**：开场即抓住注意力，有强烈好奇心驱动，用户停留意愿极高\n- **7-8分**：开场较吸引人，有一定好奇心，用户愿意继续观看\n- **5-6分**：开场普通，缺乏亮点，用户可能继续观看但容易流失\n- **3-4分**：开场平淡，缺乏吸引力，用户容易划走\n- **1-2分**：开场无趣，完全无法吸引用户\n\n### 2. 逻辑性（Logic）\n- **9-10分**：产品介绍层次分明，卖点递进清晰，从痛点→方案→证据→行动完美衔接\n- **7-8分**：逻辑较清晰，卖点有条理，过渡自然\n- **5-6分**：逻辑基本通顺，但部分衔接生硬\n- **3-4分**：逻辑混乱，卖点堆砌，缺乏条理\n- **1-2分**：完全没有逻辑，东一句西一句\n\n### 3. 感染力（Emotion）\n- **9-10分**：情感充沛，能引发强烈共鸣，让用户产生\"我也想要\"的冲动\n- **7-8分**：有一定情感表达，能打动部分用户\n- **5-6分**：情感表达一般，缺乏感染力\n- **3-4分**：语气平淡，像念稿，缺乏情感\n- **1-2分**：完全无感情，机械式朗读\n\n### 4. 专业性（Professional）\n- **9-10分**：产品知识准确，数据详实，有权威背书，用户信任度极高\n- **7-8分**：产品介绍较专业，有一定数据支撑\n- **5-6分**：产品介绍基本准确，但缺乏深度\n- **3-4分**：产品介绍有明显错误或夸大\n- **1-2分**：产品介绍错误百出，完全不专业\n\n## 输出格式\n\n请严格按照以下格式输出评分结果：\n\n### 评分总览\n| 维度 | 分数 | 评语 |\n|------|------|------|\n| 吸引力 | X/10 | 一句话评语 |\n| 逻辑性 | X/10 | 一句话评语 |\n| 感染力 | X/10 | 一句话评语 |\n| 专业性 | X/10 | 一句话评语 |\n| **综合** | **X/10** | - |\n\n### 优点\n- 列出2-3个具体优点\n\n### 待改进\n- 列出2-3个具体改进建议\n\n### 优化方向\n- 给出1-2个最关键的优化方向\n\n直接给出评分结果，不要多余的解释。',1,'2026-06-23 12:24:55','2026-06-23 12:24:55');
/*!40000 ALTER TABLE `scoring_configs` ENABLE KEYS */;
UNLOCK TABLES;

