INSERT INTO `script_templates` VALUES (8,'移动宽带套餐直播脚本','preset','通信','## 开场白（30秒）\n\"家人们，宽带选得好，上网没烦恼！今天给大家带来移动宽带超值套餐，网速快、价格低、服务好！\"\n\n## 产品介绍（2分钟）\n1. **套餐内容**\n   - 带宽：[100M/200M/500M/1000M]\n   - 流量：[是否含手机流量]\n   - 通话：[是否含通话时长]\n\n2. **核心卖点**\n   - 网速稳定：光纤入户，玩游戏不卡顿\n   - 价格实惠：月费低至[X]元，比营业厅更优惠\n   - 安装便捷：预约后[X]天内上门安装\n\n3. **适用场景**\n   - 家庭上网：看视频、刷抖音不缓冲\n   - 居家办公：视频会议流畅稳定\n   - 游戏娱乐：低延迟，团战不掉线\n\n## 互动环节（1分钟）\n\"家里宽带到期的扣1，想换宽带的扣2！\"\n\"觉得网速重要还是价格重要的？网速扣A，价格扣B\"\n\n## 促单话术（1分钟）\n\"今天直播间下单，首年月费只要[X]元，还送[路由器/话费]！\"\n\"名额有限，只有[X]个名额，抢完恢复原价！\"\n\"现在下单，明天就能安排上门安装！\"\n\n## 结尾（30秒）\n\"宽带选移动，生活更轻松！赶紧下单，享受飞一般的网速体验！记得关注我们，更多优惠等着你！\"\n','适用于移动宽带套餐推广的直播脚本模板',1,'2026-06-23 03:19:27','2026-06-23 03:19:27');
/*!40000 ALTER TABLE `script_templates` ENABLE KEYS */;
UNLOCK TABLES;

