INSERT INTO `script_versions` VALUES (1,'d7cf103f997f46269355424dd1b400bb','aa17ed93','generated','正在根据您的需求生成直播脚本，请稍候...\n\n## 开场白（30秒）\n\"家人们，今天给大家带来一款超级好用的【玻尿酸水光精华液】！我自己用了3个月，皮肤真的变好了！你看我这脸，是不是又水又嫩？姐妹们，今天这波福利真的不能错过！\"\n\n## 产品介绍（2分钟）\n1. **产品背景**\n   - 品牌故事：【悦肤泉】，专注玻尿酸护肤8年，王炸成分就是三重玻尿酸！\n   - 核心技术：三重分子玻尿酸技术，大分子锁水、中分子补水、小分子渗透肌底\n\n2. **产品卖点**\n   - 卖点1：**超强补水** + 实验室数据：使用4周后皮肤含水量提升62%！\n   - 卖点2：**修护屏障** + 用户反馈：\'用了半个月，脸颊泛红明显改善了，上妆不卡粉了！\'\n   - 卖点3：**性价比超高** + 对比优势：市面上同类精华至少300+，咱们这款才99，效果不打折！\n\n3. **使用方法**\n   - 步骤1：早晚洁面后，取2-3滴均匀涂抹全脸\n   - 步骤2：轻轻拍打吸收，再叠加面霜，锁住水分效果翻倍！\n\n## 互动环节（1分钟）\n\"有没有姐妹用过类似的产品？评论区告诉我你们的体验！\"\n\"觉得这个价格可以接受的扣1，觉得贵的扣2\"\n\n## 促单话术（1分钟）\n\"今天直播间专属价格，原价299→现价99，只有200份！\"\n\"下单的姐妹记得截图发评论区，抽5位送同款精华小样套装！手慢无，赶紧去拍！\"\n\n## 结尾（30秒）\n\"感谢大家的支持！记得关注直播间，下次还有更多好物分享！没抢到的姐妹别急，关注我，福利常来！\"\n\n---\n\n## ✅ 完成\n\n直播脚本生成完毕！\n\n💡 **下一步建议：**\n- 想对脚本进行质量评估？回复「**打分**」即可获取详细评分\n- 想优化脚本内容？回复「**订正**」即可获取优化版本\n- 想分析脚本结构？回复「**分析**」即可获取结构分析',NULL,'2026-06-23 02:48:25'),(2,'7dfad3ab14114b12b264cf3bb0cfbbe2','14974677','generated','你好！很高兴为你服务！😊\n\n我是你的直播话术助手，可以帮你：\n- 🎬 **生成直播脚本** —— 只要告诉我产品信息，我就能为你量身定做直播脚本\n- 📊 **话术打分评价** —— 从吸引力、逻辑性、感染力、专业性等多个维度打分\n- ✏️ **话术订正优化** —— 修正表达、优化结构、增加互动，让话术更有说服力\n- 🔍 **分析脚本结构** —— 检查脚本完整性，给出改进建议\n- 💡 **回答直播技巧** —— 关于直播的任何问题，都可以问我\n\n请问你今天有什么需要帮助的吗？比如你想为某款产品生成一个直播脚本，还是想优化现有的直播话术？',NULL,'2026-06-23 03:11:08'),(3,'7dfad3ab14114b12b264cf3bb0cfbbe2','c7977264','generated','\n\n[错误] 大模型调用失败: Backend error: HTTP 429',NULL,'2026-06-23 03:11:16'),(4,'7dfad3ab14114b12b264cf3bb0cfbbe2','8ba645dc','generated','\n\n[错误] 大模型调用失败: Backend error: HTTP 429',NULL,'2026-06-23 03:11:22'),(5,'7dfad3ab14114b12b264cf3bb0cfbbe2','7404ef59','generated','正在根据您的需求生成直播脚本，请稍候...\n\n## 开场白（30秒）\n\"家人们，今天给大家带来一款超级好用的【水光嫩肤精华液】！我自己用了2个月，皮肤真的像剥了壳的鸡蛋一样透亮！你们看我的脸，是不是比之前白了一个度？这可不是吹的，今天不买真的会后悔！\"\n\n## 产品介绍（2分钟）\n1. **产品背景**\n   - 品牌故事：咱们这个【柔美肌】品牌，专注美白护肤10年了，专业度绝对在线！\n   - 核心技术：用的是【微分子玻尿酸+烟酰胺】黄金组合，渗透力超强，直达皮肤底层！\n\n2. **产品卖点**\n   - 卖点1：提亮肤色！用了7天，皮肤亮度提升30%，实验室数据说话！\n   - 卖点2：淡化细纹！好多姐妹用了之后